>> +static void fill_pattern(char *buf, unsigned long size, unsigned int seed)
>> +{
>> +	unsigned long i;
>> +
>> +	for (i = 0; i < size; i++)
>> +		buf[i] = (char)pattern_byte(seed, i);
>> +}
