>> +				 unsigned int seed, unsigned long offset)
>> +{
>> +	unsigned long i;
>> +
>> +	for (i = 0; i < size; i++)
>> +		if ((unsigned char)buf[i] != pattern_byte(seed, offset + i))
>> +			return false;
>> +	return true;
>> +}
